using System.Net.WebSockets;
using System.Text;
using System.Text.Json;
using Nova.Client.Protocol;
namespace Nova.Client.Core.Realtime;
public enum RealtimeConnectionState { Closed,Connecting,Connected,Authenticating,Ready,Reconnecting,Offline,AuthenticationFailed }
public sealed class RealtimeConnectionManager { readonly Uri endpoint;readonly Func<CancellationToken,Task<string?>> tokenProvider;ClientWebSocket? socket;readonly JsonSerializerOptions json=new(JsonSerializerDefaults.Web);public RealtimeConnectionState State{get;private set;}=RealtimeConnectionState.Closed;public event EventHandler<string>? EventReceived;public RealtimeConnectionManager(Uri endpoint,Func<CancellationToken,Task<string?>> tokenProvider){this.endpoint=endpoint;this.tokenProvider=tokenProvider;}public async Task ConnectAsync(CancellationToken ct=default){if(socket is{State:WebSocketState.Open or WebSocketState.Connecting})return;socket?.Dispose();socket=new();State=RealtimeConnectionState.Connecting;await socket.ConnectAsync(endpoint,ct);State=RealtimeConnectionState.Authenticating;var token=await tokenProvider(ct)??throw new InvalidOperationException("No access token is available.");var auth=JsonSerializer.Serialize(new WebSocketEnvelope("auth",token),json);await socket.SendAsync(Encoding.UTF8.GetBytes(auth),WebSocketMessageType.Text,true,ct);State=RealtimeConnectionState.Connected;_=ReceiveLoopAsync(ct);}async Task ReceiveLoopAsync(CancellationToken ct){if(socket is null)return;var buffer=new byte[16384];while(socket.State==WebSocketState.Open&&!ct.IsCancellationRequested){using var message=new MemoryStream();WebSocketReceiveResult result;do{result=await socket.ReceiveAsync(buffer,ct);if(result.MessageType==WebSocketMessageType.Close){State=RealtimeConnectionState.Closed;return;}message.Write(buffer,0,result.Count);}while(!result.EndOfMessage);var text=Encoding.UTF8.GetString(message.ToArray());if(text.Contains("\"type\":\"ready\"",StringComparison.Ordinal))State=RealtimeConnectionState.Ready;EventReceived?.Invoke(this,text);}}public async ValueTask DisposeAsync(){if(socket is{State:WebSocketState.Open})await socket.CloseAsync(WebSocketCloseStatus.NormalClosure,"Client shutdown",CancellationToken.None);socket?.Dispose();socket=null;State=RealtimeConnectionState.Closed;}}
